const wrapWords = (t, n) => String(t || '').split(' ').reduce((ls, w) => { const last = ls[ls.length - 1]; if (last && `${last} ${w}`.length <= n) ls[ls.length - 1] = `${last} ${w}`; else ls.push(w); return ls; }, []);
const coverOf = (kind) => (f, a, l) => {
  const [title, by = ''] = String(l || '').split('|');
  const kids = kind === 'kids', exam = kind === 'exam';
  const font = kids ? 'Trebuchet MS,Arial,sans-serif' : exam ? 'Arial,Helvetica,sans-serif' : 'Georgia,serif';
  const lines = wrapWords(title, exam ? 10 : 12), size = exam ? 26 : kids ? 26 : 24, top = exam ? 120 : 104;
  const motif = { novel: `<circle cx="153" cy="230" r="28" fill="${a}" opacity=".85"/><path d="M95 262 Q153 236 211 262" stroke="${a}" stroke-width="3" fill="none"/>`,
    poem: `<path d="M153 268 Q118 236 153 196 Q188 236 153 268 Z" fill="${a}" opacity=".85"/><path d="M153 268 V206" stroke="${f}" stroke-width="2"/>`,
    kids: `${[[100, 220, 14], [196, 236, 18], [150, 268, 10]].map(([x, y, r]) => `<path d="M${x} ${y - r} L${x + r * 0.3} ${y - r * 0.3} L${x + r} ${y} L${x + r * 0.3} ${y + r * 0.3} L${x} ${y + r} L${x - r * 0.3} ${y + r * 0.3} L${x - r} ${y} L${x - r * 0.3} ${y - r * 0.3} Z" fill="${a}"/>`).join('')}`,
    exam: `<rect x="72" y="214" width="176" height="44" fill="${a}"/><text x="160" y="243" text-anchor="middle" font-family="${font}" font-weight="800" font-size="18" fill="#fff">2027 EDITION</text>` }[kind] || '';
  return `<rect x="58" y="40" width="190" height="300" rx="3" fill="${f}"/>${exam ? `<rect x="58" y="40" width="190" height="56" fill="${a}"/>` : `<rect x="88" y="70" width="140" height="2" fill="${a}"/>`}<rect x="58" y="40" width="14" height="300" fill="#000" opacity=".2"/><rect x="72" y="40" width="2" height="300" fill="#fff" opacity=".18"/>${lines.map((ln, i) => `<text x="160" y="${top + i * (size + 6)}" text-anchor="middle" font-family="${font}" font-weight="${kids || exam ? 800 : 400}" font-size="${size}" fill="#fff">${esc(ln)}</text>`).join('')}${motif}<text x="160" y="316" text-anchor="middle" font-family="${font}" font-size="13" letter-spacing="1" fill="#fff" opacity=".85">${esc(by.toUpperCase())}</text>`;
};
